dict(param='HIER', score=2, stance='supports', key='messinaWitnessesSealersSeleucid2009', where='p. 177', quote="With regard to the impressions of official seals, this seems to confirm that officers of the Seleucid administration may have been in charge in both cities", note='The same official seals at Uruk and Seleucia on the Tigris.'),
dict(param='PRIV', score=2, stance='supports', key='messinaWitnessesSealersSeleucid2009', where='p. 184', quote="so we may infer that the sealers of the bullae, too, may have been witnesses and that these lost folded documents from Seleucia sealed by bullae may have concerned tax-exempt transactions between private subjects.", note='Inference from shared witness seals.'),
